<script setup>
import { computed,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Info,Clock3,MessageCircle,Layers,FileText,CheckCircle2 } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import StatusBadge from '../components/StatusBadge.vue'
import OrderAction from '../components/OrderAction.vue'
import { orderById,taskById,state,money,income,settle,setOrderStatus,stamp,imageOf } from '../lib/store'
import { requireRole,confirm,notify } from '../lib/actions'
const route=useRoute(),router=useRouter(),order=computed(()=>orderById(route.params.id)),version=ref('current'),reason=ref(''),rejectOpen=ref(false),checks=ref([])
const checklist=computed(()=>[taskById(order.value?.taskId)?.deliverables||'按任务要求交付','商品与品牌信息准确','无侵权素材，已声明 AIGC 创作'])
const files=computed(()=>{const o=order.value;if(!o)return[];if(version.value==='history'){return o.versions.find(v=>v.result==='已驳回')?.files?.filter(f=>f.image)||[]}if(o.files?.length)return o.files;return o.art==='skincare'?[1,2,3,4,5].map(i=>({uid:i,name:`示例作品-${i}.jpg`,image:`/assets/pages/delivery-${i}.webp`})):[{uid:'cover',name:'示例交付预览',image:imageOf(o.art)}]})
async function approve(){const o=order.value;if(o.status!=='待验收'||!requireRole(router,'merchant'))return;if(await confirm(`任务赏金 ¥${money(o.cents)} → 创作者所得 ¥${money(income(o.cents))}，平台服务费 ¥${money(o.cents-income(o.cents))}。本次为演示结算，确认通过验收吗？`,'确认验收与分账')){if(settle(o))notify('演示验收已通过，创作者钱包已更新')}}
function showReject(){if(!requireRole(router,'merchant'))return;if(!order.value.remainingRevisions){ElMessage.warning('免费轮次已用尽，可追加轮次或协商处理');return}rejectOpen.value=true}
function reject(){const o=order.value;if(reason.value.trim().length<10){ElMessage.warning('驳回原因须至少 10 字');return}if(o.status!=='待验收'||o.remainingRevisions<=0)return;const v=o.versions.findLast(v=>v.version===o.version);if(v){v.result='已驳回';v.reason=reason.value}else{o.versions.push({version:o.version,result:'已驳回',reason:reason.value,at:stamp(),files:o.files})}o.remainingRevisions--;o.version++;o.hours=48;setOrderStatus(o,'待交付');rejectOpen.value=false;notify('已驳回演示作品，修改轮次减少 1 轮，创作者可重新提交')}
async function extra(){if(!requireRole(router,'merchant'))return;if(await confirm(`按赏金 10%（¥${money(Math.round(order.value.cents/10))}）追加 1 轮修改。本次不会扣款。`,'模拟追加轮次')){order.value.remainingRevisions++;notify('已追加 1 轮演示修改机会')}}
</script>
<template><div v-if="order"><div class="breadcrumbs"><RouterLink to="/merchant/tasks">任务管理</RouterLink><span>/</span>{{order.title}}<span>/</span>作品验收</div><PageTitle title="作品验收"><StatusBadge :status="order.status"/></PageTitle><div class="columns wide-left"><section class="panel"><div v-if="order.status==='待验收'" class="info-note warning"><Clock3/>剩余 {{order.hours}} 小时自动验收，请及时查看作品。演示时间不会自动推进。</div><div v-else class="info-note" :class="{success:order.status==='已完成'}"><CheckCircle2/>{{order.status==='已完成'?'验收已通过，订单已完成。':'当前作品已退回修改，请等待创作者重新提交。'}}</div><div class="review-toolbar"><el-tabs v-model="version"><el-tab-pane :label="`当前版本 v${order.version}`" name="current"/><el-tab-pane label="历史版本" name="history"/></el-tabs><span class="muted small">修改轮次剩余 <strong class="price-text">{{order.remainingRevisions}}</strong> 轮</span></div><div v-if="files.length" class="image-gallery review-gallery"><div v-for="(f,i) in files" :key="f.uid" class="gallery-item"><el-image v-if="f.image" :src="f.image" :preview-src-list="files.filter(f=>f.image).map(f=>f.image)" :initial-index="i" preview-teleported :alt="f.name"/><div v-else class="file-fallback"><FileText :size="36"/>{{f.name}}</div><span v-if="f.image&&!f.image.startsWith('/assets/')" class="ai-corner">AI 生成</span></div><div v-if="version==='current'" class="gallery-total"><Layers :size="32"/><span>共 {{files.length}} 个交付文件</span></div></div><el-empty v-else description="该版本没有可预览的文件，驳回原因见版本记录" :image-size="60"/><div v-if="version==='history'" class="version-records"><p v-for="(v,i) in order.versions" :key="i"><strong>v{{v.version}} · {{v.result}}</strong><br/><span class="muted">{{v.reason||v.note}}</span></p></div><div class="divider"/><h3>交付要求核对</h3><el-checkbox-group v-model="checks" class="checklist"><el-checkbox v-for="c in checklist" :key="c" :value="c">{{c}}</el-checkbox></el-checkbox-group><p class="field-help">核对项为辅助检查。无上传文件的示例订单显示风格预览，未提供真实视频或源文件。</p></section><aside class="stack"><section class="panel"><div class="person"><img class="avatar" src="/assets/pages/creator-avatar.webp" alt="创作者示例头像"/><div><h2>{{order.creator}}</h2><span class="plain-tag">Lv.3 认证 · 示例</span></div></div><el-button class="full-button" style="margin-top:20px" @click="router.push('/messages?role=merchant&chat=creator')"><MessageCircle/>联系创作者</el-button></section><section class="panel"><h2>交付信息</h2><div class="data-lines"><div><label>已提交文件</label><strong>{{files.length}} 个</strong></div><div><label>当前版本</label><strong>v{{order.version}}</strong></div><div><label>版本说明</label><strong>{{order.versions.at(-1)?.note||'已调整背景与产品光影。'}}</strong></div></div></section><section class="panel"><h2>赏金结算</h2><div class="data-lines"><div><label>任务赏金</label><strong class="price-text">¥{{money(order.cents)}}</strong></div><div><label>创作者所得</label><strong class="price-text">¥{{money(income(order.cents))}}</strong></div><div><label>平台服务费 15%</label><strong class="price-text">¥{{money(order.cents-income(order.cents))}}</strong></div></div></section><section class="panel"><div class="review-actions"><el-button type="danger" plain :disabled="order.status!=='待验收'" @click="showReject">驳回并说明原因</el-button><el-button type="primary" :disabled="order.status!=='待验收'" @click="approve">验收通过</el-button></div><el-button v-if="order.remainingRevisions===0&&order.status==='待验收'" link type="primary" @click="extra">追加修改轮次（演示）</el-button><OrderAction v-if="order.status==='已完成'" :order="order" kind="review" style="margin-top:15px"/><p class="field-help">通过后触发分账，操作需要再次确认。</p></section></aside></div><el-dialog v-model="rejectOpen" title="请说明需要修改的内容" width="520px" class="refinement-dialog"><div class="app-ui dialog-stack"><p class="info-note warning">本次驳回将消耗 1 轮免费修改，剩余 {{Math.max(0,order.remainingRevisions-1)}} 轮。</p><el-input v-model="reason" type="textarea" :rows="5" maxlength="500" show-word-limit placeholder="请具体说明修改位置与期望效果，至少 10 字"/></div><template #footer><el-button @click="rejectOpen=false">取消</el-button><el-button type="primary" @click="reject">确认驳回</el-button></template></el-dialog></div><el-empty v-else description="未找到这份交付订单"><el-button @click="router.push('/merchant/tasks')">返回任务管理</el-button></el-empty></template>
<style scoped>.review-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:15px 0}.review-toolbar .el-tabs{min-width:0}.review-toolbar :deep(.el-tabs__header){margin:0}.gallery-total{border:1px dashed #c6cfe0;border-radius:6px;color:#8e9bb1;display:flex;flex-direction:column;gap:12px;align-items:center;justify-content:center;font-size:12px;aspect-ratio:1.05}.review-actions{display:flex;gap:10px}.review-actions .el-button{flex:1;padding:10px 12px;font-size:13px}.file-fallback{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;background:#f5f7fb;aspect-ratio:1.05;border-radius:6px;font-size:12px;color:#8794ac}.version-records{background:#f8faff;padding:15px;margin-top:20px;border-radius:6px}.version-records p{font-size:12px}@media(max-width:650px){.review-toolbar{flex-wrap:wrap}.review-actions{flex-wrap:wrap}}</style>
